export const PREFERENCES_KEY='geodecoder.digital.preferences.v1';
export const DEFAULTS=Object.freeze({text:'normal',contrast:'standard',motion:'system',music:true,musicVolume:22,effects:false,effectsVolume:70,muted:false,autoRotate:true,labels:false,resume:false,lastSection:'explore'});
export function normalize(value={}){const p={...DEFAULTS};for(const k of Object.keys(p)){const v=value?.[k];if(typeof p[k]==='boolean'&&typeof v==='boolean')p[k]=v;else if(typeof p[k]==='number'&&Number.isFinite(v))p[k]=Math.round(Math.max(0,Math.min(100,v)));}for(const [k,values] of Object.entries({text:['normal','large','largest'],contrast:['standard','strong'],motion:['system','reduce','full'],lastSection:['explore','notes','labs']}))if(values.includes(value?.[k]))p[k]=value[k];return p;}
export function createPreferences(storage){let failed=false,p;try{const raw=storage?.getItem(PREFERENCES_KEY);p=normalize(raw?JSON.parse(raw):{music:!['false','0'].includes(storage?.getItem('geodecoder.digital.music.enabled'))});if(!storage)failed=true;}catch{p=normalize();failed=true;}const listeners=new Set();return {get value(){return {...p};},get failed(){return failed;},set(patch){p=normalize({...p,...patch});try{if(!storage)throw Error();storage.setItem(PREFERENCES_KEY,JSON.stringify(p));failed=false;}catch{failed=true;}for(const fn of listeners)fn({...p});},reset(){this.set(DEFAULTS);},subscribe(fn){listeners.add(fn);return ()=>listeners.delete(fn);},reload(){try{p=normalize(JSON.parse(storage.getItem(PREFERENCES_KEY)||'{}'));for(const fn of listeners)fn({...p});}catch{failed=true;}}};}
export function controls(p){const select=(key,title,choices)=>`<label class="preference-row"><span>${title}</span><select data-pref="${key}">${choices.map(([v,t])=>`<option value="${v}" ${p[key]===v?'selected':''}>${t}</option>`).join('')}</select></label>`;const check=(key,title)=>`<label class="preference-row"><span>${title}</span><input type="checkbox" data-pref="${key}" ${p[key]?'checked':''}></label>`;const volume=(key,title)=>`<label class="preference-row"><span>${title} <output data-volume="${key}">${p[key]}%</output></span><input type="range" min="0" max="100" step="1" value="${p[key]}" data-pref="${key}" aria-label="${title}"></label>`;return `<div class="preferences"><p>Perubahan digunakan serta-merta dan disimpan pada pelayar ini.</p><fieldset><legend>Paparan &amp; Aksesibiliti</legend>${select('text','Saiz teks',[['normal','Biasa'],['large','Besar'],['largest','Lebih besar']])}${select('contrast','Kontras',[['standard','Standard'],['strong','Kontras tinggi']])}${select('motion','Animasi',[['system','Ikut sistem'],['reduce','Kurangkan'],['full','Penuh']])}<div class="preference-preview"><b>Pratonton GeoDecoder</b><p>Teroka bongkah dan bentangan. Fokus papan kekunci kekal jelas.</p><button type="button" class="button button-primary">Contoh butang</button></div></fieldset><fieldset><legend>Audio &amp; Bahasa</legend><p>Bahasa Melayu. Pilihan bahasa lain belum tersedia untuk portal ini.</p>${check('music','Muzik latar')}${volume('musicVolume','Kelantangan muzik')}${check('effects','Kesan bunyi')}${volume('effectsVolume','Kelantangan kesan bunyi')}${check('muted','Senyapkan Semua')}<button type="button" class="button button-quiet" data-test-sound>Uji kesan bunyi</button></fieldset><fieldset><legend>Pilihan Pembelajaran</legend>${check('autoRotate','Putaran automatik ketika membuka Teroka 3D')}${check('labels','Label muka pada model')}${check('resume','Sambung bahagian modul terakhir')}<p>Putaran dihentikan apabila animasi dikurangkan. Kelajuan animasi belum boleh dilaraskan dalam modul ini.</p></fieldset><p role="status" id="preferences-status"></p><button type="button" class="button button-quiet" data-reset-preferences>Pulihkan Tetapan Asal</button></div>`;}
